mapper.select:
SELECT ro.id AS id, ro.order_no AS orderNo, ro.purchase_order_id AS purchaseOrderId, po.order_no AS purchaseOrderNo, ro.supplier_id AS supplierId, s.name AS supplierName, ro.receipt_time AS receiptTime, ro.operator_name AS operatorName, ro.authorizer_name AS authorizerName, ro.delivery_order_no AS deliveryOrderNo, ro.total_amount AS totalAmount, ro.remark AS remark,
NULL AS items FROM receipt_order ro JOIN purchase_order po ON po.id = ro.purchase_order_id JOIN supplier s ON s.id = ro.supplier_id
AND ro.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND po.order_no LIKE CONCAT('%', #{q.purchaseOrderNo}, '%')
AND ro.supplier_id = #{q.supplierId}
AND ro.receipt_time >= #{beginTime}
AND ro.receipt_time < #{endTime}
AND ro.operator_name LIKE CONCAT('%', #{q.operatorName}, '%')
ORDER BY ro.id DESC
